// Typed API client.
//
// Two modes:
//  - Live (default, dev): requests are proxied through Next (/api -> FastAPI) so
//    the browser stays same-origin (see next.config.mjs rewrites).
//  - Static (NEXT_PUBLIC_STATIC_DATA=1, prod): there is no backend. Responses are
//    read from pre-baked JSON under /api-static (generated by
//    scripts/export_static_data.py) and filtered/paginated client-side. Writes
//    are applied to a localStorage overlay so the demo stays interactive at $0
//    hosting cost. See web/src/lib/static-store.ts.

import {
  applyOverlay,
  createCompetitor as storeCreate,
  deleteCompetitor as storeDelete,
  updateCompetitor as storeUpdate,
} from "./static-store";
import type {
  Change,
  Competitor,
  CompetitorCreate,
  CompetitorUpdate,
  CadencePoint,
  HiringRow,
  OverviewStats,
  Page,
  PricingPoint,
  Report,
  ReportSummary,
  Signal,
  SignalQuery,
} from "./types";

const STATIC = process.env.NEXT_PUBLIC_STATIC_DATA === "1";
const BASE = process.env.NEXT_PUBLIC_API_BASE_URL ?? "/api";
const STATIC_BASE = "/api-static";

export class ApiError extends Error {
  constructor(
    public status: number,
    message: string,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE}${path}`, {
    ...init,
    headers: { "Content-Type": "application/json", ...(init?.headers ?? {}) },
  });
  if (!res.ok) {
    let message = `Request failed (${res.status})`;
    try {
      const body = await res.json();
      message = body?.error?.message ?? body?.detail ?? message;
    } catch {
      /* non-JSON error body */
    }
    throw new ApiError(res.status, message);
  }
  if (res.status === 204) return undefined as T;
  return (await res.json()) as T;
}

function qs(params: object): string {
  const sp = new URLSearchParams();
  for (const [k, v] of Object.entries(params as Record<string, unknown>)) {
    if (v !== undefined && v !== null && v !== "") sp.set(k, String(v));
  }
  const s = sp.toString();
  return s ? `?${s}` : "";
}

// ----------------------------- static helpers ----------------------------- //

async function staticGet<T>(file: string, fallback?: T): Promise<T> {
  const res = await fetch(`${STATIC_BASE}/${file}`);
  if (!res.ok) {
    if (fallback !== undefined) return fallback;
    throw new ApiError(res.status, `Missing static data: ${file}`);
  }
  return (await res.json()) as T;
}

async function mergedCompetitors(): Promise<Competitor[]> {
  const base = await staticGet<Competitor[]>("competitors.json", []);
  return applyOverlay(base);
}

type FeedItem = Signal | Change;

function filterAndPage<T extends FeedItem>(
  items: T[],
  q: SignalQuery,
  sigKey: "significance" | "weighted_significance",
  dateKey: "extracted_at" | "detected_at",
): Page<T> {
  const sig = (r: T) => (r as unknown as Record<string, number | null>)[sigKey] ?? 0;
  const when = (r: T) => (r as unknown as Record<string, string | null>)[dateKey] ?? "";

  let rows = items;
  if (q.competitor) rows = rows.filter((r) => r.competitor_id === q.competitor);
  if (q.signal_type) rows = rows.filter((r) => r.signal_type === q.signal_type);
  if (q.min_significance != null) {
    const min = q.min_significance;
    rows = rows.filter((r) => sig(r) >= min);
  }
  if (q.date_from) rows = rows.filter((r) => when(r) >= q.date_from!);
  if (q.date_to) rows = rows.filter((r) => when(r) <= q.date_to!);

  // Newest first; changes break ties by weighted significance (mirrors the API).
  rows = [...rows].sort((a, b) => {
    const da = when(a);
    const db = when(b);
    if (da !== db) return db.localeCompare(da);
    return sig(b) - sig(a);
  });

  const total = rows.length;
  const offset = q.offset ?? 0;
  const limit = q.limit ?? 50;
  return { items: rows.slice(offset, offset + limit), total, limit, offset };
}

// --------------------------------- client --------------------------------- //

export const api = {
  overview: () =>
    STATIC
      ? staticGet<OverviewStats>("overview.json")
      : request<OverviewStats>("/stats/overview"),

  competitors: () => (STATIC ? mergedCompetitors() : request<Competitor[]>("/competitors")),

  competitor: async (id: string) => {
    if (!STATIC) return request<Competitor>(`/competitors/${id}`);
    const found = (await mergedCompetitors()).find((c) => c.id === id);
    if (!found) throw new ApiError(404, `Competitor '${id}' not found.`);
    return found;
  },

  createCompetitor: async (body: CompetitorCreate) => {
    if (!STATIC)
      return request<Competitor>("/competitors", { method: "POST", body: JSON.stringify(body) });
    return storeCreate(await staticGet<Competitor[]>("competitors.json", []), body);
  },

  updateCompetitor: async (id: string, body: CompetitorUpdate) => {
    if (!STATIC)
      return request<Competitor>(`/competitors/${id}`, {
        method: "PATCH",
        body: JSON.stringify(body),
      });
    return storeUpdate(await staticGet<Competitor[]>("competitors.json", []), id, body);
  },

  deleteCompetitor: async (id: string) => {
    if (!STATIC) return request<void>(`/competitors/${id}`, { method: "DELETE" });
    storeDelete(id);
  },

  signals: async (q: SignalQuery = {}) => {
    if (!STATIC) return request<Page<Signal>>(`/signals${qs(q)}`);
    const all = await staticGet<Signal[]>("signals.json", []);
    return filterAndPage(all, q, "significance", "extracted_at");
  },

  changes: async (q: SignalQuery = {}) => {
    if (!STATIC) return request<Page<Change>>(`/changes${qs(q)}`);
    const all = await staticGet<Change[]>("changes.json", []);
    return filterAndPage(all, q, "weighted_significance", "detected_at");
  },

  pricingHistory: (id: string) =>
    STATIC
      ? staticGet<PricingPoint[]>(`competitors/${id}/pricing-history.json`, [])
      : request<PricingPoint[]>(`/competitors/${id}/pricing-history`),

  hiring: (id: string) =>
    STATIC
      ? staticGet<HiringRow[]>(`competitors/${id}/hiring.json`, [])
      : request<HiringRow[]>(`/competitors/${id}/hiring`),

  cadence: (id: string) =>
    STATIC
      ? staticGet<CadencePoint[]>(`competitors/${id}/cadence.json`, [])
      : request<CadencePoint[]>(`/competitors/${id}/cadence`),

  reports: () =>
    STATIC ? staticGet<ReportSummary[]>("reports.json", []) : request<ReportSummary[]>("/reports"),

  report: (id: string) =>
    STATIC ? staticGet<Report>(`reports/${id}.json`) : request<Report>(`/reports/${id}`),

  reportPdfUrl: (id: string) => (STATIC ? `${STATIC_BASE}/reports/${id}.pdf` : `${BASE}/reports/${id}/pdf`),

  runPipeline: (body: { provider?: string; limit?: number }) =>
    STATIC
      ? Promise.resolve({
          status: "demo",
          detail: "Demo mode: data is pre-generated and refreshes automatically.",
        })
      : request<{ status: string; detail: string }>("/pipeline/run", {
          method: "POST",
          body: JSON.stringify(body),
        }),
};
